(function() {
    'use strict';

    class AugmentIQAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'AugmentIQ: Human-AI Decision Lab';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    aiConfidence: '82%',
                    eventProb: 0.40,
                    financials: {
                        A: { revenue: 18, govCost: 5, riskPenalty: 3, eventPenalty: 4.5 },
                        B: { revenue: 12, govCost: 3, riskPenalty: 2, eventPenalty: 2 },
                        C: { revenue: 7, govCost: 1.5, riskPenalty: 1, eventPenalty: 0.5 },
                        D: { revenue: 2, govCost: 0.5, riskPenalty: 0.5, eventPenalty: 0 }
                    },
                    en: {
                        title: `Round 1: AI Adoption Governance Scope`,
                        briefing: `Meridian Health Systems ($1.4B revenue, 12,400 employees) has deployed AI decision-support across four areas: talent acquisition, dynamic pricing, risk stratification, and crisis detection. As Division GM, you must define the scope of AI authority in each domain and invest in governance infrastructure. The board expects measurable efficiency gains, but regulators and clinicians demand human oversight.<br><br>Your $37M discretionary capital must last all 5 rounds. Invest wisely in governance now — or pay later.`,
                        aiRec: `Full AI implementation across all domains with comprehensive governance (Option A across all dimensions) — projected +$18M net revenue impact.`,
                        eventText: `Regulatory Notice: Brazil Ministry of Health issues algorithmic transparency guidance requiring explainability documentation and human override authority. Aggressive automation costs increase 25%.`,
                        decisions: [
                            { label: `Hiring AI Authority`, options: { A: `Full AI: screens, schedules, HR approval only`, B: `Partial: AI screens resumes, humans interview`, C: `Conservative: HR screens, AI supplements ranking`, D: `Pilot: AI for high-volume roles only` } },
                            { label: `Pricing AI Authority`, options: { A: `Real-time dynamic: AI adjusts daily, human review >15% variance`, B: `Recommendations: AI suggests daily, manager approves`, C: `Periodic: AI analyzes weekly, quarterly adjustments`, D: `Conservative: AI suggests, <3% annual authority` } },
                            { label: `Risk Stratification Authority`, options: { A: `Automated triage: AI classifies and initiates care`, B: `AI-assisted: AI suggests tier, physician decides`, C: `Supplementary: AI risk scores only, no automation`, D: `Transparency: AI scores in clinical notes only` } },
                            { label: `Crisis Detection Authority`, options: { A: `Autonomous alerting with pre-defined escalation`, B: `Notification with gate: AI alerts, manager escalates`, C: `Daily briefing integration`, D: `Advisory: weekly risk report only` } },
                            { label: `Governance Investment`, options: { A: `Comprehensive: $5M — full audit, explainability, bias monitoring`, B: `Moderate: $3M — audit trails, compliance, escalation`, C: `Minimal: $1.5M — documentation and escalation only`, D: `Deferred: $0.5M — basic documentation` } }
                        ]
                    },
                    es: {
                        title: `Ronda 1: Alcance de la Gobernanza de Adopcion de IA`,
                        briefing: `Meridian Health Systems ($1.4B en ingresos, 12,400 empleados) ha desplegado soporte de decisiones con IA en cuatro areas: adquisicion de talento, precios dinamicos, estratificacion de riesgo y deteccion de crisis. Como Gerente General de Division, debes definir el alcance de la autoridad de la IA en cada dominio e invertir en infraestructura de gobernanza. La junta espera ganancias de eficiencia medibles, pero los reguladores y clinicos exigen supervision humana.<br><br>Tu capital discrecional de $37M debe alcanzar para las 5 rondas. Invierte con criterio en gobernanza ahora, o paga despues.`,
                        aiRec: `Implementacion completa de IA en todos los dominios con gobernanza integral (Opcion A en todas las dimensiones) — impacto neto proyectado de +$18M en ingresos.`,
                        eventText: `Aviso regulatorio: El Ministerio de Salud de Brasil emite directrices de transparencia algoritmica que exigen documentacion de explicabilidad y autoridad de anulacion humana. La automatizacion agresiva incrementa costos en 25%.`,
                        decisions: [
                            { label: `Autoridad de IA en Contratacion`, options: { A: `IA total: filtra, agenda, RRHH solo aprueba`, B: `Parcial: IA filtra hojas de vida, humanos entrevistan`, C: `Conservador: RRHH filtra, IA complementa ranking`, D: `Piloto: IA solo para roles de alto volumen` } },
                            { label: `Autoridad de IA en Precios`, options: { A: `Dinamico en tiempo real: IA ajusta diario, revision humana >15% de variacion`, B: `Recomendaciones: IA sugiere diario, gerente aprueba`, C: `Periodico: IA analiza semanal, ajustes trimestrales`, D: `Conservador: IA sugiere, autoridad <3% anual` } },
                            { label: `Autoridad en Estratificacion de Riesgo`, options: { A: `Triage automatizado: IA clasifica e inicia atencion`, B: `Asistido por IA: IA sugiere nivel, medico decide`, C: `Complementario: solo puntajes de riesgo de IA, sin automatizacion`, D: `Transparencia: puntajes de IA solo en notas clinicas` } },
                            { label: `Autoridad en Deteccion de Crisis`, options: { A: `Alertas autonomas con escalamiento predefinido`, B: `Notificacion con filtro: IA alerta, gerente escala`, C: `Integracion en informe diario`, D: `Consultivo: solo informe de riesgo semanal` } },
                            { label: `Inversion en Gobernanza`, options: { A: `Integral: $5M — auditoria completa, explicabilidad, monitoreo de sesgos`, B: `Moderada: $3M — trazas de auditoria, cumplimiento, escalamiento`, C: `Minima: $1.5M — solo documentacion y escalamiento`, D: `Diferida: $0.5M — documentacion basica` } }
                        ]
                    }
                },
                {
                    aiConfidence: '74%',
                    eventProb: 0.35,
                    financials: {
                        A: { revenue: -2, govCost: 1.2, riskPenalty: -1.2, eventPenalty: -0.5 },
                        B: { revenue: -1, govCost: 0.6, riskPenalty: -0.5, eventPenalty: -0.3 },
                        C: { revenue: -0.4, govCost: 0.15, riskPenalty: 0.8, eventPenalty: 1.5 },
                        D: { revenue: 1.5, govCost: 0, riskPenalty: 1.2, eventPenalty: 2.5 }
                    },
                    en: {
                        title: `Round 2: Hiring Algorithm Bias and Trust`,
                        briefing: `The hiring AI has been flagged for gender bias: it recommends men 61% vs women 39%, despite women comprising 58% of the nursing applicant pool. Root cause: training data spans 10 years when women were only 44% of hires. On the upside, AI improved scheduling efficiency by 40% and identified missed high-quality candidates.<br><br>You must decide how to respond: suspend, modify, audit, or accept the system. Stakeholders are watching — clinicians, HR, the board, and potentially regulators.`,
                        aiRec: `Modify algorithm input — remove gender variable and retrain on recent 3-year data (Option D for Immediate Response). Projected 85% bias reduction while maintaining 90% of efficiency gains.`,
                        eventText: `Competitive Intelligence: A major competitor publicly announces AI hiring practices with demographic parity commitment. Creates public pressure if Meridian has not acted on bias.`,
                        decisions: [
                            { label: `Immediate Response`, options: { A: `Suspend AI hiring immediately, return to manual`, B: `Continue AI but mandate 60% female interview slots`, C: `Reduce AI authority, humans make final decisions with monitoring`, D: `Modify algorithm: remove gender variable, retrain on 3-year data` } },
                            { label: `Bias Remediation`, options: { A: `External audit: $400K comprehensive algorithmic audit`, B: `Internal: 4-week data science analysis, $100K`, C: `Accept with monitoring: document bias, human flagging`, D: `Fairness constraints: optimize for performance AND demographic parity` } },
                            { label: `Stakeholder Communication`, options: { A: `Full transparency: disclose to all, publish quarterly metrics`, B: `Targeted: inform HR and board only, improve prospectively`, C: `Minimal: compliance files and internal HR only`, D: `Positive framing: highlight improvements, avoid bias details` } },
                            { label: `Broader Model Review`, options: { A: `Comprehensive audit across all AI domains`, B: `Targeted: audit pricing and risk models (highest impact)`, C: `Narrow: address hiring bias only`, D: `Reactive: monitor, audit only if problems emerge` } },
                            { label: `Governance Enhancement`, options: { A: `Major: $1.2M — fairness tools, dashboards, external audits`, B: `Moderate: $600K — monitoring systems, internal reviews`, C: `Minimal: $150K documentation`, D: `No incremental investment` } }
                        ]
                    },
                    es: {
                        title: `Ronda 2: Sesgo y Confianza en el Algoritmo de Contratacion`,
                        briefing: `El algoritmo de contratacion fue senalado por sesgo de genero: recomienda hombres 61% vs mujeres 39%, pese a que las mujeres son 58% del grupo de postulantes de enfermeria. Causa raiz: los datos de entrenamiento abarcan 10 anos cuando las mujeres eran solo 44% de las contrataciones. Del lado positivo, la IA mejoro la eficiencia de programacion 40% e identifico candidatos de alta calidad que se habian pasado por alto.<br><br>Debes decidir como responder: suspender, modificar, auditar o aceptar el sistema. Los interesados observan: clinicos, RRHH, la junta y posiblemente los reguladores.`,
                        aiRec: `Modificar la entrada del algoritmo — eliminar la variable de genero y reentrenar con datos de los ultimos 3 anos (Opcion D en Respuesta Inmediata). Reduccion de sesgo proyectada de 85% conservando 90% de las ganancias de eficiencia.`,
                        eventText: `Inteligencia competitiva: Un competidor importante anuncia publicamente sus practicas de contratacion con IA con compromiso de paridad demografica. Genera presion publica si Meridian no ha actuado sobre el sesgo.`,
                        decisions: [
                            { label: `Respuesta Inmediata`, options: { A: `Suspender la IA de contratacion de inmediato, volver a manual`, B: `Continuar con IA pero exigir 60% de entrevistas a mujeres`, C: `Reducir autoridad de IA, humanos deciden con monitoreo`, D: `Modificar algoritmo: eliminar variable de genero, reentrenar con 3 anos` } },
                            { label: `Remediacion del Sesgo`, options: { A: `Auditoria externa: $400K auditoria algoritmica integral`, B: `Interna: analisis de 4 semanas de ciencia de datos, $100K`, C: `Aceptar con monitoreo: documentar sesgo, marcado humano`, D: `Restricciones de equidad: optimizar desempeno Y paridad demografica` } },
                            { label: `Comunicacion con Interesados`, options: { A: `Transparencia total: divulgar a todos, publicar metricas trimestrales`, B: `Focalizada: informar solo a RRHH y junta, mejorar a futuro`, C: `Minima: archivos de cumplimiento y RRHH interno`, D: `Enfoque positivo: destacar mejoras, evitar detalles del sesgo` } },
                            { label: `Revision Ampliada del Modelo`, options: { A: `Auditoria integral en todos los dominios de IA`, B: `Focalizada: auditar modelos de precios y riesgo (mayor impacto)`, C: `Acotada: abordar solo el sesgo de contratacion`, D: `Reactiva: monitorear, auditar solo si surgen problemas` } },
                            { label: `Refuerzo de Gobernanza`, options: { A: `Mayor: $1.2M — herramientas de equidad, tableros, auditorias externas`, B: `Moderado: $600K — sistemas de monitoreo, revisiones internas`, C: `Minimo: $150K documentacion`, D: `Sin inversion incremental` } }
                        ]
                    }
                },
                {
                    aiConfidence: '79%',
                    eventProb: 0.45,
                    financials: {
                        A: { revenue: 2.2, govCost: 0.5, riskPenalty: 1.8, eventPenalty: 2.5 },
                        B: { revenue: 0.9, govCost: 0.3, riskPenalty: 0.7, eventPenalty: 1.0 },
                        C: { revenue: 0.6, govCost: 0.2, riskPenalty: -0.2, eventPenalty: 0.3 },
                        D: { revenue: -1.5, govCost: 0.1, riskPenalty: -0.3, eventPenalty: -0.5 }
                    },
                    en: {
                        title: `Round 3: AI Pricing Under Market Crisis`,
                        briefing: `Crisis: A new competitor launches aggressive price reductions targeting your premium outpatient clinics. Simultaneously, a major employer (12% of private insurance referrals) announces benefit restructuring that will reduce patient volume 8-10%.<br><br>The pricing AI recommends an immediate 12% price reduction to maintain volume and market share. Your CFO warns this compresses margins below acceptable thresholds. Your Chief Strategy Officer argues AI speed provides competitive advantage in volatile markets.`,
                        aiRec: `Implement immediate 12% price reduction across outpatient services within 48 hours (Option A for Pricing Action). Volume protection projected at +$2.2M; margin compression of -$1.8M.`,
                        eventText: `Regulatory Change: A major private payer announces new contracting rules requiring pricing algorithm transparency and explicit human approval of algorithm-driven price changes.`,
                        decisions: [
                            { label: `Pricing Action`, options: { A: `Full AI recommendation: 12% reduction across outpatient, 48 hours`, B: `Partial: 8% reduction over 1 week with communication`, C: `Selective: 12% only in competing services, 10% in vulnerable segments`, D: `Maintain pricing: preserve margins, develop value propositions` } },
                            { label: `Communication Strategy`, options: { A: `Speed-focused: announce immediately for competitive edge`, B: `Balanced: transparent to staff, payers, patients`, C: `Selective: quality to premium, price to volume-sensitive`, D: `Value-first: no pricing announcement, quality messaging` } },
                            { label: `Margin Protection`, options: { A: `Accept compression: 2.1% margin decline, invest in AI efficiency`, B: `Modest: 5% admin reduction, 1.1% net margin decline`, C: `Balanced: 8% price cut + 7% admin reduction, breakeven`, D: `Reject compression: maintain margin, non-price differentiation` } },
                            { label: `Competitor Response Planning`, options: { A: `Anticipate escalation: model price war scenarios`, B: `Monitor and adapt: track moves, quarterly reviews`, C: `Hold firm: position against price wars`, D: `Proactive differentiation: invest in innovation and outcomes` } },
                            { label: `AI-Human Integration for Pricing`, options: { A: `Full AI authority: daily adjustments, human review >10% changes`, B: `AI with gates: AI recommends, manager approves, crisis committee weekly`, C: `Human-led with AI support: committee decides, AI provides analysis`, D: `Human decision-making: AI provides analysis only` } }
                        ]
                    },
                    es: {
                        title: `Ronda 3: Precios con IA en Crisis de Mercado`,
                        briefing: `Crisis: Un nuevo competidor lanza reducciones agresivas de precios apuntando a tus clinicas ambulatorias premium. A la vez, un gran empleador (12% de las referencias de seguro privado) anuncia una reestructuracion de beneficios que reducira el volumen de pacientes 8-10%.<br><br>La IA de precios recomienda una reduccion inmediata de 12% para mantener volumen y participacion de mercado. Tu CFO advierte que esto comprime margenes por debajo de umbrales aceptables. Tu Director de Estrategia argumenta que la velocidad de la IA da ventaja competitiva en mercados volatiles.`,
                        aiRec: `Implementar reduccion inmediata de precios de 12% en servicios ambulatorios en 48 horas (Opcion A en Accion de Precios). Proteccion de volumen proyectada en +$2.2M; compresion de margen de -$1.8M.`,
                        eventText: `Cambio regulatorio: Un pagador privado importante anuncia nuevas reglas de contratacion que exigen transparencia del algoritmo de precios y aprobacion humana explicita de cambios de precio impulsados por algoritmos.`,
                        decisions: [
                            { label: `Accion de Precios`, options: { A: `Recomendacion completa de IA: reduccion 12% ambulatorio, 48 horas`, B: `Parcial: reduccion 8% en 1 semana con comunicacion`, C: `Selectiva: 12% solo en servicios en competencia, 10% en segmentos vulnerables`, D: `Mantener precios: preservar margenes, desarrollar propuestas de valor` } },
                            { label: `Estrategia de Comunicacion`, options: { A: `Enfocada en velocidad: anunciar de inmediato por ventaja competitiva`, B: `Equilibrada: transparente con personal, pagadores, pacientes`, C: `Selectiva: calidad a premium, precio a sensibles al precio`, D: `Valor primero: sin anuncio de precios, mensaje de calidad` } },
                            { label: `Proteccion de Margen`, options: { A: `Aceptar compresion: caida de margen 2.1%, invertir en eficiencia de IA`, B: `Modesta: reduccion administrativa 5%, caida neta de margen 1.1%`, C: `Equilibrada: recorte de precio 8% + reduccion administrativa 7%, punto de equilibrio`, D: `Rechazar compresion: mantener margen, diferenciacion sin precio` } },
                            { label: `Planeacion de Respuesta del Competidor`, options: { A: `Anticipar escalamiento: modelar escenarios de guerra de precios`, B: `Monitorear y adaptar: seguir movimientos, revisiones trimestrales`, C: `Mantenerse firme: posicionarse contra guerras de precios`, D: `Diferenciacion proactiva: invertir en innovacion y resultados` } },
                            { label: `Integracion IA-Humano en Precios`, options: { A: `Autoridad total de IA: ajustes diarios, revision humana >10% de cambios`, B: `IA con filtros: IA recomienda, gerente aprueba, comite de crisis semanal`, C: `Liderado por humanos con apoyo de IA: comite decide, IA aporta analisis`, D: `Decision humana: IA solo aporta analisis` } }
                        ]
                    }
                },
                {
                    aiConfidence: '78%',
                    eventProb: 0.50,
                    financials: {
                        A: { revenue: 1.8, govCost: 0.3, riskPenalty: 0.8, eventPenalty: -3.0 },
                        B: { revenue: 0.9, govCost: 0.2, riskPenalty: 0.3, eventPenalty: -1.0 },
                        C: { revenue: -0.2, govCost: 0.4, riskPenalty: -0.5, eventPenalty: 2.0 },
                        D: { revenue: -0.4, govCost: 0.5, riskPenalty: -0.8, eventPenalty: 1.5 }
                    },
                    en: {
                        title: `Round 4: Market Exit vs. AI Recommendation`,
                        briefing: `Meridian Chilean operations are underperforming: 8.2% margin vs. 12% target. Competitive intensity has increased, regulatory rates declined 6%, and political uncertainty surrounds healthcare privatization.<br><br>The AI model (78% confidence) recommends reducing Chilean operations by 50% — close 2 of 4 clinics and reduce hospital beds by 30%. Your Chief Strategy Officer argues the Chilean entry was strategic positioning with long-term optionality that the AI model cannot capture.`,
                        aiRec: `Reduce Chilean operations 50%: close 2 clinics, reduce beds 30%. Redirect $12M capital to core Brazil operations with higher-confidence ROI.`,
                        eventText: `Positive Market Signal: Chile announces healthcare privatization incentives and payment increases for private providers. Validates strategic patience if presence maintained.`,
                        decisions: [
                            { label: `Market Positioning`, options: { A: `Aggressive exit: reduce operations 50% within 6 months`, B: `Partial exit: reduce 25%, consolidate to best location`, C: `Stability: maintain footprint, targeted improvements`, D: `Market commitment: increase investment, pursue growth` } },
                            { label: `Capital Reallocation`, options: { A: `Redirect to core: redeploy $12M to high-confidence projects`, B: `Selective: $6M to core, retain $6M for Chilean growth`, C: `Reinvest in Chile: direct freed capital to Chilean operations`, D: `Diversify: allocate across multiple initiatives` } },
                            { label: `Algorithm Decision Role`, options: { A: `Trust algorithm: accept as final decision, accelerate action`, B: `Algorithm-informed: primary input with human validation`, C: `Augmented: AI identifies pattern, human assesses viability`, D: `Subordinate: AI is one input, weight human judgment more` } },
                            { label: `Risk Management`, options: { A: `Accept concentration: reduce diversification, focus core markets`, B: `Maintain diversification: keep Chile as portfolio hedge`, C: `Structured turnaround: 18-month plan with specific targets`, D: `Monitor: minimal investment, watch for market changes` } },
                            { label: `Stakeholder Management`, options: { A: `Decisive: announce as strategic refocus and portfolio optimization`, B: `Transparent: communicate reasoning to all stakeholders`, C: `Stabilizing: emphasize commitment, manage expectations`, D: `Growth narrative: communicate increased commitment` } }
                        ]
                    },
                    es: {
                        title: `Ronda 4: Salida del Mercado vs. Recomendacion de IA`,
                        briefing: `Las operaciones chilenas de Meridian tienen bajo desempeno: margen 8.2% vs. meta de 12%. La intensidad competitiva aumento, las tarifas regulatorias cayeron 6% y hay incertidumbre politica sobre la privatizacion de la salud.<br><br>El modelo de IA (78% de confianza) recomienda reducir las operaciones chilenas en 50% — cerrar 2 de 4 clinicas y reducir camas hospitalarias en 30%. Tu Director de Estrategia argumenta que la entrada a Chile fue un posicionamiento estrategico con opcionalidad de largo plazo que el modelo de IA no captura.`,
                        aiRec: `Reducir operaciones chilenas 50%: cerrar 2 clinicas, reducir camas 30%. Redirigir $12M de capital a operaciones centrales en Brasil con mayor confianza de ROI.`,
                        eventText: `Senal de mercado positiva: Chile anuncia incentivos de privatizacion de salud y aumentos de pago para proveedores privados. Valida la paciencia estrategica si se mantiene la presencia.`,
